  ('pages.blog.portage-salarial-product-owner-scrum-master.auto.heading.1gq6cv2', '/blog/portage-salarial-product-owner-scrum-master', 'heading', 'Portage salarial pour Product Owner et Scrum Master'),
  ('pages.blog.portage-salarial-product-owner-scrum-master.auto.heading.3g5w6n', '/blog/portage-salarial-product-owner-scrum-master', 'heading', 'Un statut adapté aux missions de transformation'),
