  ('pages.qui-sommes-nous.auto.paragraph.16inr34', '/qui-sommes-nous', 'paragraph', 'Accompagnement dans le suivi de mission'),
  ('pages.qui-sommes-nous.auto.paragraph.173z8z7', '/qui-sommes-nous', 'paragraph', 'Concevoir des infrastructures plus agiles, plus fiables et plus performantes pour accélérer la transformation technologique des organisations.'),
  ('pages.qui-sommes-nous.auto.paragraph.17a37nm', '/qui-sommes-nous', 'paragraph', 'GitLab CI'),
  ('pages.qui-sommes-nous.auto.paragraph.17kpq20', '/qui-sommes-nous', 'paragraph', 'DevSecOps'),
  ('pages.qui-sommes-nous.auto.paragraph.189r6ym', '/qui-sommes-nous', 'paragraph', 'Les missions en cybersécurité demandent souvent une forte expertise, une grande autonomie et une capacité à intervenir rapidement dans des contextes sensibles. Le portage salarial permet au consultant de conserver son indépendance tout en bénéficiant d’un cadre contractuel et administratif structuré.'),
  ('pages.qui-sommes-nous.auto.paragraph.18zq9we', '/qui-sommes-nous', 'paragraph', 'Observabilité, résilience et performance'),
  ('pages.qui-sommes-nous.auto.paragraph.18zuzxn', '/qui-sommes-nous', 'paragraph', 'Sensibilisation'),
  ('pages.qui-sommes-nous.auto.paragraph.19c5f4', '/qui-sommes-nous', 'paragraph', 'Coaching individuel et collectif'),
