  ('pages.qui-sommes-nous.auto.paragraph.1a5drsb', '/qui-sommes-nous', 'paragraph', 'Indicateurs de performance'),
  ('pages.qui-sommes-nous.auto.paragraph.1a7rrq0', '/qui-sommes-nous', 'paragraph', 'Cartographie des risques'),
  ('pages.qui-sommes-nous.auto.paragraph.1a7vo24', '/qui-sommes-nous', 'paragraph', 'Accompagnement personnalisé du consultant'),
  ('pages.qui-sommes-nous.auto.paragraph.1ajjcrt', '/qui-sommes-nous', 'paragraph', 'Rapports d’avancement'),
  ('pages.qui-sommes-nous.auto.paragraph.1akr8v2', '/qui-sommes-nous', 'paragraph', 'Conception de solutions basées sur les grands modèles de langage, assistants métiers, moteurs de recherche internes, systèmes RAG et automatisations intelligentes.'),
  ('pages.qui-sommes-nous.auto.paragraph.1am41sc', '/qui-sommes-nous', 'paragraph', 'Roadmap'),
  ('pages.qui-sommes-nous.auto.paragraph.1azuwfa', '/qui-sommes-nous', 'paragraph', 'Gestion des contrats et avenants'),
  ('pages.qui-sommes-nous.auto.paragraph.1bey7rb', '/qui-sommes-nous', 'paragraph', 'Réalisation d’audits organisationnels et techniques, cartographie des risques, préparation aux certifications et accompagnement dans la mise en conformité réglementaire.'),
  ('pages.qui-sommes-nous.auto.paragraph.1bqarei', '/qui-sommes-nous', 'paragraph', 'Analytics Engineer'),
  ('pages.qui-sommes-nous.auto.paragraph.1bx7ktl', '/qui-sommes-nous', 'paragraph', 'Les missions peuvent concerner aussi bien la définition d’une stratégie de cybersécurité que la sécurisation opérationnelle des environnements cloud, des identités, des applications, des réseaux ou des données sensibles.'),
  ('pages.qui-sommes-nous.auto.paragraph.1carmwo', '/qui-sommes-nous', 'paragraph', 'L’approche en bref'),
  ('pages.qui-sommes-nous.auto.paragraph.1cbgqms', '/qui-sommes-nous', 'paragraph', 'Définition de feuilles de route cybersécurité, réalisation d’analyses de maturité, mise en place de politiques de sécurité et accompagnement des directions dans le pilotage des risques numériques.'),
  ('pages.qui-sommes-nous.auto.paragraph.1cn8kzw', '/qui-sommes-nous', 'paragraph', 'The Big Porters rejoint le groupe. C’est une ESN spécialisée IT : là où le portage salarie un consultant qui a trouvé sa mission, l’ESN répond à une entreprise qui cherche encore son profil.'),
  ('pages.qui-sommes-nous.auto.paragraph.1d1uc2c', '/qui-sommes-nous', 'paragraph', 'Pour le consultant qui a trouvé sa mission et veut exercer en autonomie dans un cadre salarié.'),
  ('pages.qui-sommes-nous.auto.paragraph.1d4yyjs', '/qui-sommes-nous', 'paragraph', 'Microsoft Azure'),
  ('pages.qui-sommes-nous.auto.paragraph.1dd62gw', '/qui-sommes-nous', 'paragraph', 'Conception ou optimisation de chaînes CI/CD, réduction des interventions manuelles et accélération de la mise en production des applications.'),
  ('pages.qui-sommes-nous.auto.paragraph.1dn621m', '/qui-sommes-nous', 'paragraph', 'Prise en charge de la facturation'),
  ('pages.qui-sommes-nous.auto.paragraph.1dsgqdy', '/qui-sommes-nous', 'paragraph', 'Les engagements, les accès et les contraintes du client sont rendus lisibles.'),
  ('pages.qui-sommes-nous.auto.paragraph.1dxknbo', '/qui-sommes-nous', 'paragraph', 'Conseil, assistance et sensibilisation'),
