  ('pages.qui-sommes-nous.auto.paragraph.2kfi1h', '/qui-sommes-nous', 'paragraph', 'Parler le langage des consultants cyber, data, IA, cloud, DevOps, produit, projet et transformation.'),
  ('pages.qui-sommes-nous.auto.paragraph.33ndu7', '/qui-sommes-nous', 'paragraph', 'Rapports d’audit et recommandations prioritaires'),
  ('pages.qui-sommes-nous.auto.paragraph.3ef7gj', '/qui-sommes-nous', 'paragraph', 'Lean'),
  ('pages.qui-sommes-nous.auto.paragraph.3g2yxt', '/qui-sommes-nous', 'paragraph', 'Accompagnement humain et disponible'),
  ('pages.qui-sommes-nous.auto.paragraph.3ki6f7', '/qui-sommes-nous', 'paragraph', 'Le mémoire technique du groupe formalise une continuité de bout en bout : cadrage, exécution, recette, capitalisation et transfert de connaissances.'),
  ('pages.qui-sommes-nous.auto.paragraph.3y6sa3', '/qui-sommes-nous', 'paragraph', 'The Porters porte les experts de la donnée et de l’intelligence artificielle qui interviennent sur toute la chaîne de valeur, depuis la collecte et la structuration des données jusqu’à leur analyse, leur visualisation et leur exploitation par des modèles avancés.'),
  ('pages.qui-sommes-nous.auto.paragraph.4d78x3', '/qui-sommes-nous', 'paragraph', 'Intégration et déploiement continus'),
