  ('pages.qui-sommes-nous.auto.paragraph.4z3np3', '/qui-sommes-nous', 'paragraph', 'Conception de plateformes data, construction de pipelines, organisation des flux, fiabilisation des sources et industrialisation du traitement des données.'),
  ('pages.qui-sommes-nous.auto.paragraph.52m20o', '/qui-sommes-nous', 'paragraph', 'Program Manager'),
