  ('pages.qui-sommes-nous.auto.paragraph.8lxstx', '/qui-sommes-nous', 'paragraph', 'Automatisation de la création, du déploiement et de la configuration des infrastructures afin d’améliorer la rapidité, la fiabilité et la reproductibilité.'),
  ('pages.qui-sommes-nous.auto.paragraph.8zl37m', '/qui-sommes-nous', 'paragraph', 'Product Discovery'),
  ('pages.qui-sommes-nous.auto.paragraph.92o5hg', '/qui-sommes-nous', 'paragraph', 'Création d’indicateurs, exploration des données, développement de tableaux de bord et production d’analyses utiles aux équipes métiers et aux directions.'),
