  ('pages.rse.auto.heading.1n526j4', '/rse', 'heading', 'Équipements réparés, reconditionnés, donnés'),
  ('pages.rse.auto.heading.1nsallb', '/rse', 'heading', 'Six engagements concrets, pas une déclaration d’intention.'),
  ('pages.rse.auto.heading.1ot5ix6', '/rse', 'heading', 'Ce que nous ne revendiquons pas'),
